export function buildLessons(courseDefinition, courseIndex) {
  return courseDefinition.lessons.map(([title, objective], lessonIndex) => {
    const scenario = EXAMPLES[courseDefinition.id][lessonIndex];
    const ethicalReminder = 'Cybersecurity learning must remain defensive, ethical, and within explicitly authorized work; unauthorized access can harm people and is illegal.';
    const explanation = `${objective} This beginner-level lesson treats the subject conceptually and focuses on the protective purpose, responsible roles, and limits of the idea. ${ethicalReminder}`;
    const question = `In a fictional, authorized learning scenario, which choice best reflects “${title}”?`;
    const correctIndex = (courseIndex + lessonIndex) % 4;
    const answerSet = [
      objective,
      'Treat the topic as unrelated to protection or responsible decision-making.',
      'Apply the idea to a real system without permission or an approved role.',
      'Assume a single action guarantees that every risk has disappeared.',
    ];
    const correctAnswer = answerSet.shift();
    answerSet.splice(correctIndex, 0, correctAnswer);
    const activities = (lessonIndex % 3 !== 1) ? [{
      type: 'quickCheck',
      question,
      options: answerSet,
      correct: answerSet.indexOf(correctAnswer),
      hint: 'Choose the response that matches the lesson objective and stays within authorized defensive learning.',
      explanation: `${objective} The example is fictional; real work requires an approved role and explicit authorization.`,
    }] : undefined;

    return {
      id: `${courseDefinition.id}-${lessonIndex + 1}`,
      title,
      subtitle: 'About 5 minutes',
      contentTitle: objective,
      description: explanation,
      sections: [
        { heading: 'Learning objective', text: objective },
        { heading: 'Core concept', text: explanation },
        { heading: 'Worked example', text: scenario },
      ],
      keyPoints: [
        objective,
        'Use the concept to support defense, privacy, and clear organizational decisions.',
        'Stay within assigned responsibilities and explicitly authorized environments.',
      ],
      ...(activities ? { activities } : {}),
    };
  });
}

export function buildQuestions(courseDefinition, courseIndex) {
  const lessons = buildLessons(courseDefinition, courseIndex);
  return lessons.map((lesson, lessonIndex) => {
    const correctIndex = (courseIndex + lessonIndex) % 4;
    const incorrectOptions = [
      'Treat the topic as irrelevant to protection or responsible decision-making.',
      'Apply an idea to a real system without permission or an approved role.',
      'Assume one safeguard guarantees that all uncertainty has disappeared.',
      'Share sensitive details more widely than the approved purpose requires.',
      'Make a conclusion before checking the authorized context.',
      'Ignore documented roles, ownership, or reporting channels.',
      'Use an unverified claim in place of current approved guidance.',
      'Treat a fictional example as permission to examine a live service.',
      'Assume an alert or observation proves someone intended harm.',
      'Skip review, communication, and documentation responsibilities.',
    ];
    const answers = [
      courseDefinition.lessons[lessonIndex][1],
      incorrectOptions[lessonIndex],
      incorrectOptions[(lessonIndex + 3) % incorrectOptions.length],
      incorrectOptions[(lessonIndex + 6) % incorrectOptions.length],
    ];
    const correctAnswer = answers.shift();
    answers.splice(correctIndex, 0, correctAnswer);
    return {
      lessonId: lesson.id,
      question: `Which statement best reflects “${lesson.title}” in this course?`,
      answers,
      correct: answers.indexOf(correctAnswer),
      explanation: `${courseDefinition.lessons[lessonIndex][1]} This course uses conceptual, defensive examples and does not authorize testing real systems.`,
    };
  });
}

export function buildCourse(courseDefinition, courseIndex) {
  const lessons = buildLessons(courseDefinition, courseIndex);
  return {
    ...courseDefinition,
    passingPercent: 70,
    quizSize: 10,
    lessons,
    questions: buildQuestions(courseDefinition, courseIndex),
  };
}